package com.bank.slo;

import java.util.concurrent.atomic.AtomicLong;

// The SLI: a precisely-measured ratio of good events to total valid events.
public class SliCalculator {
    private final AtomicLong goodEvents = new AtomicLong();
    private final AtomicLong totalEvents = new AtomicLong();

    // Record one transfer: success = a GOOD event; all count toward total.
    public void record(boolean success) {
        totalEvents.incrementAndGet();
        if (success) goodEvents.incrementAndGet();
    }

    // SLI value as a percentage of successful transfers.
    public double sliPercent() {
        long total = totalEvents.get();
        return total == 0 ? 100.0 : 100.0 * goodEvents.get() / total;
    }

    public long getTotal() { return totalEvents.get(); }
}
