package com.bank.slo;

import java.util.logging.Logger;

// Holds the internal SLO and external SLA, and classifies the current SLI.
public class ServiceLevels {
    private static final Logger log = Logger.getLogger(ServiceLevels.class.getName());

    private final double sloPercent;   // internal objective (stricter)
    private final double slaPercent;   // external contract (looser)

    public ServiceLevels(double sloPercent, double slaPercent) {
        // enforce the golden rule: SLO must be stricter than SLA
        if (sloPercent < slaPercent)
            throw new IllegalArgumentException("SLO must be >= SLA to keep a buffer");
        this.sloPercent = sloPercent;
        this.slaPercent = slaPercent;
    }

    public enum Status { MEETING_SLO, BELOW_SLO_ABOVE_SLA, SLA_BREACH }

    public Status classify(double sliPercent) {
        if (sliPercent >= sloPercent) {
            log.info(() -> String.format("MEETING SLO: SLI %.3f%% >= SLO %.3f%% — healthy",
                sliPercent, sloPercent));
            return Status.MEETING_SLO;
        } else if (sliPercent >= slaPercent) {
            log.warning(() -> String.format(
                "BELOW SLO (%.3f%% < %.3f%%) but ABOVE SLA %.3f%% — internal alarm, "
                + "react now, NO contract breach (buffer working)",
                sliPercent, sloPercent, slaPercent));
            return Status.BELOW_SLO_ABOVE_SLA;
        } else {
            log.severe(() -> String.format(
                "SLA BREACH: SLI %.3f%% < SLA %.3f%% — contractual penalties (service credits)",
                sliPercent, slaPercent));
            return Status.SLA_BREACH;
        }
    }
}
