package com.bank.slo;

import java.util.logging.*;

// Runnable demo: healthy, then degraded (buffer absorbs it), then breaching.
public class SloDemo {
    private static final Logger log = Logger.getLogger(SloDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        ch.setLevel(Level.ALL);
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — transfer service level targets");
        // Internal SLO stricter (99.95%) than external SLA (99.9%) — the buffer.
        ServiceLevels levels = new ServiceLevels(99.95, 99.9);

        // Phase 1: healthy — 10000 transfers, 2 failures -> 99.98% (>= SLO)
        SliCalculator healthy = new SliCalculator();
        for (int i = 0; i < 9998; i++) healthy.record(true);
        for (int i = 0; i < 2; i++) healthy.record(false);
        levels.classify(healthy.sliPercent());

        // Phase 2: degraded — 10000 transfers, 4 failures -> 99.96%? recompute below
        SliCalculator degraded = new SliCalculator();
        for (int i = 0; i < 9996; i++) degraded.record(true);
        for (int i = 0; i < 4; i++) degraded.record(false);   // 99.96% still >= SLO
        // push it between SLO and SLA: 8 failures -> 99.92%
        SliCalculator between = new SliCalculator();
        for (int i = 0; i < 9992; i++) between.record(true);
        for (int i = 0; i < 8; i++) between.record(false);     // 99.92% (<SLO, >SLA)
        levels.classify(between.sliPercent());

        // Phase 3: breaching — 20 failures -> 99.80% (< SLA)
        SliCalculator breach = new SliCalculator();
        for (int i = 0; i < 9980; i++) breach.record(true);
        for (int i = 0; i < 20; i++) breach.record(false);
        levels.classify(breach.sliPercent());
    }
}
